(function(){
const $=id=>document.getElementById(id),pages=$('pages');
const STANDALONE_LOGO='data:image/png;base64,';
function get(k,d){try{return JSON.parse(sessionStorage.getItem(k)||localStorage.getItem(k)||JSON.stringify(d));}catch(e){return d;}}
function put(k,v){try{sessionStorage.setItem(k,JSON.stringify(v));}catch(e){}}
const cfg=get('cable_design_main_config',{}), allRows=get('cable_spec_rows',[]), selectedRows=get('cable_spec_selected_rows',[]);
// Specification Sheet displays only rows checked in the source dimension table.
const rows=Array.isArray(selectedRows)&&selectedRows.length?allRows.filter((_,i)=>selectedRows.includes(i)):[];
const tech=get('cable_tech_rows',[]), selected=get('cable_spec_selected_columns',[0,1,2,3,5,7,8,9,10,11]);
let techSelected=get('cable_tech_selected_columns',['cores','size','r20','rhot','ir','amp','L','C','X','Z','Z0']);
let sections=get('cable_spec_sheet_sections',{dimension:true,tech:true});
if(!sections||typeof sections!=='object')sections={dimension:true,tech:true};
if(sections.dimension===undefined)sections.dimension=true;
if(sections.tech===undefined)sections.tech=true;
function sectionOn(name){return sections[name]!==false;}
function bindSectionOptions(){
 const dim=$('includeDimensionSection'), techBox=$('includeTechSection');
 if(dim){dim.checked=sectionOn('dimension');dim.addEventListener('change',()=>{sections.dimension=dim.checked;put('cable_spec_sheet_sections',sections);build();});}
 if(techBox){techBox.checked=sectionOn('tech');techBox.addEventListener('change',()=>{sections.tech=techBox.checked;put('cable_spec_sheet_sections',sections);build();});}
}
// Add the new reactance field to legacy saved Technical Data column selections once.
if(!techSelected.includes('X')&&!get('cable_tech_reactance_column_added',false)){techSelected.push('X');put('cable_tech_selected_columns',techSelected);put('cable_tech_reactance_column_added',true);}
let form=get('cable_spec_sheet_form',{revisions:[{rev:'0',date:'',description:'',prepared:'',reviewed:'',approved:''}]});
function val(k,d=''){return form[k]??d;}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function headInput(k,d='',max=16){return `<input data-form="${k}" maxlength="${max}" value="${esc(val(k,d))}">`;}
function titleInput(){
 return `<div class="title-lines"><span class="title-main">PRODUCT SPECIFICATION SHEET</span><input class="title-product" data-form="title" maxlength="180" aria-label="Product name" value="${esc(val('title',cfg.cable_name||cfg.product_name||'Cable Specification'))}"><span class="title-sub">Cable design, dimensional data and electrical technical information</span></div>`;
}
function header(n,total){
 return `<div class="page-head"><img src="assets/ls-cable-logo.png" alt="LS Cable & System"><div class="sheet-title">${titleInput()}</div><div class="doc-meta"><div><b>Spec. No.</b>${headInput('specNo','',15)}</div><div><b>Rev. No.</b>${headInput('revNo','0',6)}</div><div><b>Issue Date</b>${headInput('issueDate','',10)}</div><div><b>Page</b><span class="page-no">${n} of ${total}</span></div></div></div>`;
}
function field(label,key,defaultValue='',inline=false){return `<div class="field${inline?' inline-field':''}"><label>${label}</label><input data-form="${key}" value="${esc(val(key,defaultValue))}"></div>`;}
function bullets(label,key){
 return `<div class="wide-field"><label>${label}</label><div class="split-bullets"><textarea class="bullet-input" data-form="${key}Left}" rows="4" placeholder="• Enter item">${esc(val(key+'Left'))}</textarea><textarea class="bullet-input" data-form="${key}Right" rows="4" placeholder="• Enter item">${esc(val(key+'Right'))}</textarea></div></div>`;
}
function singleBullets(label,key,plain=false,prefix=''){
 const legacy=key==='appliedStd'?[val('appliedStdLeft'),val('appliedStdRight')].filter(Boolean).join('\n'):
              key==='mainProperties'?[val('mainPropertiesLeft'),val('mainPropertiesRight')].filter(Boolean).join('\n'):'';
 const content=plain?String(val(key,legacy)).replace(/^\s*•\s*/gm,''):val(key,legacy);
 const inputClass=plain?'plain-input':'bullet-input';
 const placeholder=plain?'Enter item':'• Enter item';
 const input=`<textarea class="${inputClass}" data-form="${key}" rows="4" placeholder="${placeholder}">${esc(content)}</textarea>`;
 return `<div class="wide-field">${label?`<label>${label}</label>`:''}${prefix?`<div class="prefixed-input"><span class="input-prefix">${esc(prefix)}</span>${input}</div>`:input}</div>`;
}
function revRows(){let r=form.revisions||[];if(!r.length)r=[{rev:'0',date:'',description:'',prepared:'',reviewed:'',approved:''}];return r.map((x,i)=>`<tr>${['rev','date','description','prepared','reviewed','approved'].map(k=>`<td><input data-rev="${i}" data-key="${k}" value="${esc(x[k]||'')}"></td>`).join('')}</tr>`).join('');}
function drawing(key,msg){const d=sessionStorage.getItem(key);return d?`<img src="${d}" alt="${key}">`:`<div class="empty">${msg}</div>`;}
function coreUnitLabel(){
 const type=String(cfg.core_type||'CORE').toUpperCase();
 return type==='PAIR'?'Pairs':type==='TRIAD'?'Triads':type==='QUAD'?'Quads':'Cores';
}
function conductorSizeUnit(){
 const standard=String(cfg.conductorStandard||cfg.conductor_standard||'IEC').toUpperCase();
 return (standard==='ASTM'||standard==='IEEE_1580')?'AWG/kcmil':'SQMM';
}
function sizeOnly(value){
 return String(value||'').replace(/\s*(?:SQMM|AWG|KCMIL|MCM)\b/gi,'').trim();
}
const defs=[[0,`No. of ${coreUnitLabel()}`,r=>r.cores||''],[1,`Cond. Size (${conductorSizeUnit()})`,r=>sizeOnly(r.sizeText||r.nominalArea||'')],[2,'Cond. O.D. (mm)',r=>r.condOD],[3,'Insulation Thick. (mm)',r=>r.insuThick],[4,'Assembly O.D. (mm)',r=>r.assemblyOD],[5,'Inner Covering Thick. (mm)',r=>r.beddingThick],[6,'Inner Sheath O.D. (mm)',r=>r.beddingOD],[7,'Armor Wire / Tape (mm)',r=>r.armorVal],[8,'Outer Sheath Thick. (mm)',r=>r.sheathThick],[9,'Overall O.D. (mm)',r=>r.overallOD],[10,'O.D. ± (mm)',r=>r.tolerance==null?'':`±${r.tolerance}`],[11,'Approx. Weight (kg/km)',r=>Number(r.weight||0).toLocaleString()],[12,'Material Cost (KRW/m)',r=>Number(r.totalCostKm||0).toLocaleString()]];
function dimTable(chunk){const use=defs.filter(d=>selected.includes(d[0]));return `<table class="sheet-table"><thead><tr>${use.map(d=>`<th>${d[1].replace(' ','<br>')}</th>`).join('')}</tr></thead><tbody>${chunk.map(x=>`<tr>${use.map(d=>`<td>${esc(d[2](x.r)||'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
const techDefs=[
 ['cores',`No. of ${coreUnitLabel()}`,(t,x)=>x.r.cores||''],
 ['size',`Conductor Size<br><span class="unit">(${conductorSizeUnit()})</span>`,(t,x)=>sizeOnly(x.r.sizeText||x.r.nominalArea||'')],
 ['r20','DC Resistance at 20°C<br><span class="unit">(Ω/km)</span>'],
 ['rhot','DC Resistance at Hot<br><span class="unit">(Ω/km)</span>'],
 ['ir','Insulation Resistance<br><span class="unit">(MΩ·km)</span>'],
 ['amp','Allowable Current<br><span class="unit">(A)</span>'],
 ['L','Inductance L<br><span class="unit">(mH/km)</span>'],
 ['C','Capacitance C<br><span class="unit">(μF/km)</span>'],
 ['X','Reactance X<br><span class="unit">(Ω/km)</span>'],
 ['Z','Impedance Z<br><span class="unit">(Ω/km)</span>'],
 ['Z0','Zero-sequence Impedance Z0<br><span class="unit">(Ω/km)</span>']
];
function techTable(chunk){const use=techDefs.filter(d=>techSelected.includes(d[0]));return `<table class="sheet-table"><thead><tr>${use.map(d=>`<th>${d[1]}</th>`).join('')}</tr></thead><tbody>${chunk.map(x=>{const t=tech[x.i]||{};return `<tr>${use.map(d=>`<td>${esc(d[2]?d[2](t,x):(t[d[0]]||''))}</td>`).join('')}</tr>`;}).join('')}</tbody></table>`;}
function chunks(items,limit){if(!items.length)return[];const out=[],ordered=items.slice().sort((a,b)=>(Number(a.r.cores)||0)-(Number(b.r.cores)||0)||((Number(a.r.nominalArea)||parseFloat(a.r.sizeText)||0)-(Number(b.r.nominalArea)||parseFloat(b.r.sizeText)||0)));let cur=[];for(let i=0;i<ordered.length;){const key=String(ordered[i].r.cores||''),g=[];while(i<ordered.length&&String(ordered[i].r.cores||'')===key)g.push(ordered[i++]);if(g.length<=limit){if(cur.length&&cur.length+g.length>limit){out.push(cur);cur=[];}cur=cur.concat(g);continue;}if(cur.length){out.push(cur);cur=[];}for(let j=0;j<g.length;){const size=String(g[j].r.nominalArea||g[j].r.sizeText||''),sg=[];while(j<g.length&&String(g[j].r.nominalArea||g[j].r.sizeText||'')===size)sg.push(g[j++]);if(cur.length&&cur.length+sg.length>limit){out.push(cur);cur=[];}if(sg.length>limit){while(sg.length)out.push(sg.splice(0,limit));}else cur=cur.concat(sg);}}if(cur.length)out.push(cur);return out;}
function mainContent(){return `<div class="sub-title">Revision History</div><table class="revtable"><colgroup><col style="width:8%"><col style="width:13%"><col style="width:35%"><col style="width:14%"><col style="width:15%"><col style="width:15%"></colgroup><thead><tr><th>Rev. No.</th><th>Issue Date</th><th>Description Of Change</th><th>Prepared By</th><th>Reviewed By</th><th>Approved By</th></tr></thead><tbody id="revBody">${revRows()}</tbody></table><button class="add-row" onclick="addRevision()">Add Revision Row</button><div class="sub-title">Cable Information</div><div class="cable-info-layout"><div class="visuals"><div class="visual-cell"><div class="visual-title">2D Section</div><div class="drawing">${drawing('cable_2d_drawing','2D section drawing is not available.')}</div></div><div class="visual-cell"><div class="visual-title">3D Section</div><div class="drawing">${drawing('cable_3d_drawing','3D section drawing is not available.')}</div><div class="drawing-note">For Reference Only, Not To Scale</div></div></div><div class="cable-details"><div class="field-grid">${field('Voltage','voltage',cfg.v_rating||'',true)}${field('Cable Type','cableType',cfg.cable_name||cfg.product_name||'',true)}${field('Max. Conductor Temperature','maxConductorTemp','',true)}</div>${singleBullets('Applicable Standards','appliedStd')}${singleBullets('Key Features','mainProperties')}</div></div><div class="sub-title">Cable Identification</div><div class="identification-grid"><div>${singleBullets('Insulation','insulation')}</div><div>${singleBullets('Sheath','sheath',true)}</div></div><div class="sub-title">Cable Marking</div><div class="marking-field">${singleBullets('','cableMarking',true,'(e.g.)')}</div>`;}
function footer(){return '<div class="page-footer">Please consult with the supplier in advance and obtain approval prior to contract execution.</div>';}
function adjustTitleText(){
 document.querySelectorAll('.title-product').forEach(el=>{
   const max=16,min=10;
   el.style.fontSize=max+'px';
   for(let size=max;size>=min;size--){
     el.style.fontSize=size+'px';
     if(el.scrollWidth<=el.clientWidth+1) break;
   }
 });
}
function build(){
 const indexed=rows.map((r,i)=>({r,i}));
 const techRowSelection=get('cable_tech_selected_rows',null);
 const techIndexed=tech.map((t,i)=>({r:rows[i]||{},t,i})).filter(x=>!Array.isArray(techRowSelection)||techRowSelection.includes(x.i));
 const includeDimensions=sectionOn('dimension'), includeTech=sectionOn('tech');
 const dims=includeDimensions?chunks(indexed,24):[], techs=includeTech?chunks(techIndexed,26):[];
 const total=1+(includeDimensions?Math.max(1,dims.length):0)+(includeTech?Math.max(1,techs.length):0);
 let no=1;
 pages.innerHTML=`<section class="page main-page">${header(no++,total)}${mainContent()}${footer()}</section>`;
 if(includeDimensions){
   if(dims.length)dims.forEach(c=>pages.insertAdjacentHTML('beforeend',`<section class="page">${header(no++,total)}<div class="sub-title">Dimension Table</div>${dimTable(c)}${footer()}</section>`));
   else pages.insertAdjacentHTML('beforeend',`<section class="page">${header(no++,total)}<div class="empty">No selected specification table rows.</div>${footer()}</section>`);
 }
 if(includeTech){
   if(techs.length)techs.forEach(c=>pages.insertAdjacentHTML('beforeend',`<section class="page">${header(no++,total)}<div class="sub-title">Technical Data</div>${techTable(c)}${footer()}</section>`));
   else pages.insertAdjacentHTML('beforeend',`<section class="page">${header(no++,total)}<div class="empty">No selected technical data rows.</div>${footer()}</section>`);
 }
 adjustTitleText();
}
window.saveForm=function(){document.querySelectorAll('[data-form]').forEach(e=>form[e.dataset.form]=e.value);const r=[];document.querySelectorAll('#revBody tr').forEach(tr=>{const x={};tr.querySelectorAll('[data-key]').forEach(e=>x[e.dataset.key]=e.value);r.push(x);});form.revisions=r.length?r:[{rev:'0',date:'',description:'',prepared:'',reviewed:'',approved:''}];put('cable_spec_sheet_form',form);};
window.addRevision=function(){window.saveForm();form.revisions.push({rev:'',date:'',description:'',prepared:'',reviewed:'',approved:''});put('cable_spec_sheet_form',form);build();};
window.goMain=function(){if(window.opener&&!window.opener.closed)window.opener.focus();else window.location.href='index.html';};
function bullet(text){return String(text||'').split('\n').map(x=>x.trim()?x.replace(/^\s*(?:•\s*)?/,'• '):'').join('\n');}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList.contains('bullet-input')){e.preventDefault();const el=e.target,p=el.selectionStart;el.setRangeText('\n• ',p,el.selectionEnd,'end');window.saveForm();}});
document.addEventListener('input',e=>{if(e.target.dataset.form){if(e.target.classList.contains('bullet-input')){const p=e.target.selectionStart;e.target.value=bullet(e.target.value);e.target.setSelectionRange(Math.min(p,e.target.value.length),Math.min(p,e.target.value.length));}document.querySelectorAll(`[data-form="${e.target.dataset.form}"]`).forEach(x=>{if(x!==e.target)x.value=e.target.value;});if(e.target.dataset.form==='title')adjustTitleText();window.saveForm();}if(e.target.dataset.key)window.saveForm();});
document.addEventListener('focusin',e=>{if(e.target.classList.contains('bullet-input')&&!e.target.value.trim())e.target.value='• ';});

// Save 버튼: 브라우저가 지원하면 저장 위치 선택 창을 열고, 지원하지 않으면 일반 다운로드로 저장합니다.
function specFileName(){
  // 파일명은 Spec. No.가 아닌 사용자가 입력한 사양서 제목과 Revision으로 생성합니다.
  const title=String(form.title||cfg.cable_name||cfg.product_name||'cable-specification').trim().replace(/[\\/:*?"<>|]+/g,'-')||'cable-specification';
  const revNo=String(form.revNo||'0').trim().replace(/[\\/:*?"<>|]+/g,'-')||'0';
  return `${title} rev.${revNo}.html`;
}
async function saveHtmlFile(html,fileName){
  const blob=new Blob([html],{type:'text/html;charset=utf-8'});
  if(window.showSaveFilePicker){
    try{
      const handle=await window.showSaveFilePicker({
        suggestedName:fileName,
        types:[{description:'HTML file',accept:{'text/html':['.html']}}]
      });
      const writable=await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return;
    }catch(e){
      // 사용자가 저장 창을 취소한 경우에는 다운로드를 시작하지 않습니다.
      if(e && e.name==='AbortError') return;
    }
  }
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download=fileName; a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),500);
}

// 현재 사양서를 독립 HTML 파일로 저장합니다. 도면 이미지와 입력값을 파일에 포함합니다.
window.exportStandaloneHtml=async function(){
  window.saveForm();
  const fileName=specFileName();
  const copy=document.documentElement.cloneNode(true);
  copy.querySelectorAll('input').forEach((el,i)=>{
    const src=document.querySelectorAll('input')[i];
    el.setAttribute('value',src ? src.value : el.value);
  });
  copy.querySelectorAll('textarea').forEach((el,i)=>{
    const src=document.querySelectorAll('textarea')[i];
    el.textContent=src ? src.value : el.value;
  });
  copy.querySelectorAll('img[src="assets/ls-cable-logo.png"]').forEach(img=>img.src=STANDALONE_LOGO);
  copy.querySelectorAll('script[src]').forEach(el=>el.remove());
  copy.querySelectorAll('.add-row').forEach(el=>el.removeAttribute('onclick'));
  const toolbar=copy.querySelector('.toolbar');
  if(toolbar) toolbar.innerHTML='<img src="'+STANDALONE_LOGO+'"><span>Specification Sheet</span><i></i><button class="btn" onclick="saveStandalone()">Save</button><button class="btn" onclick="window.print()">Print / PDF</button>';
  const helper=`<script>
  function standaloneFileName(){
    // 독립 저장본도 화면에서 입력한 제목을 파일명으로 사용합니다.
    var title=(document.querySelector('[data-form="title"]')||{}).value||'cable-specification';
    var rev=(document.querySelector('[data-form="revNo"]')||{}).value||'0';
    title=String(title).trim().replace(/[\\\\/:*?"<>|]+/g,'-')||'cable-specification';
    rev=String(rev).trim().replace(/[\\\\/:*?"<>|]+/g,'-')||'0';
    return title+' rev.'+rev+'.html';
  }
  async function saveStandalone(){
    var root=document.documentElement.cloneNode(true);
    root.querySelectorAll('input').forEach(function(el){el.setAttribute('value',el.value);});
    root.querySelectorAll('textarea').forEach(function(el){el.textContent=el.value;});
    var blob=new Blob(['<!doctype html>'+root.outerHTML],{type:'text/html;charset=utf-8'});
    var name=standaloneFileName();
    if(window.showSaveFilePicker){
      try{
        var handle=await window.showSaveFilePicker({suggestedName:name,types:[{description:'HTML file',accept:{'text/html':['.html']}}]});
        var writable=await handle.createWritable(); await writable.write(blob); await writable.close(); return;
      }catch(e){if(e&&e.name==='AbortError')return;}
    }
    var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},500);
  }
  document.addEventListener('click',function(e){
    if(!e.target.classList.contains('add-row')) return;
    var body=document.getElementById('revBody');if(!body) return;
    var tr=document.createElement('tr');
    ['rev','date','description','prepared','reviewed','approved'].forEach(function(k){var td=document.createElement('td'),input=document.createElement('input');input.setAttribute('data-key',k);td.appendChild(input);tr.appendChild(td);});body.appendChild(tr);
  });
  <\/script>`;
  const html='<!doctype html>'+copy.outerHTML.replace('</body>',helper+'</body>');
  await saveHtmlFile(html,fileName);
};
bindSectionOptions();
build();
})();
